:root {
    --width: 720px;
    --font-main: 'Press Start 2P', cursive;
    --font-secondary: 'Ubuntu', sans-serif;
    --font-scale: 1em;
    --page-background: #131956;
    --background-color: #4d68ee;
    --stripe-color: #4861e0;
    --heading-color: #ffffff;
    --text-color: #ffffff;
    --link-color: #ffe45c;
    --visited-color: #ff9ee6;
    --code-background-color: #dfe5ff;
    --code-color: #131956;
    --blockquote-color: #ffffff;
}

* {
    box-sizing: border-box;
}

html {
    padding: 0 12px;
    background-color: var(--page-background);
}

body {
    position: relative;
    max-width: var(--width);
    margin: 25px auto;
    padding: 0;
    background-color: var(--background-color);
    color: var(--text-color);
    font-family: var(--font-secondary);
    font-size: var(--font-scale);
    line-height: 1.6;
    text-align: left;
    overflow-wrap: break-word;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    font-family: var(--font-main);
    font-weight: 400;
    line-height: 1.5;
    color: var(--heading-color);
    text-shadow: 2px 2px 0 var(--page-background);
}

h1 {
    font-size: clamp(1.25rem, 4.5vw, 2rem);
}

h2 {
    font-size: clamp(1rem, 3.5vw, 1.4rem);
}

h3 {
    font-size: clamp(.9rem, 3vw, 1.1rem);
}

h4,
h5,
h6 {
    font-size: .85rem;
}

a {
    color: var(--text-color);
    cursor: pointer;
    text-decoration: underline var(--link-color);
    text-decoration-thickness: 3px;
    text-underline-offset: 3px;
    text-shadow: 1px 2px 0 var(--page-background);
}

a:hover {
    color: var(--page-background);
    background: var(--link-color);
    text-decoration: none;
    text-shadow: none;
}

:focus-visible {
    outline: 3px solid var(--link-color);
    outline-offset: 2px;
}

::selection {
    color: var(--page-background);
    background: var(--link-color);
}

header,
footer {
    position: relative;
    padding: 4px;
    background-image: linear-gradient(45deg, var(--background-color) 25%, var(--stripe-color) 25%, var(--stripe-color) 50%, var(--background-color) 50%, var(--background-color) 75%, var(--stripe-color) 75%, var(--stripe-color) 100%);
    background-size: 56.57px 56.57px;
    background-clip: padding-box;
    border: 2px solid transparent;
    box-shadow:
        0 0 0 1px var(--page-background),
        0 0 0 4px #fff,
        0 0 0 5px var(--page-background);
    overflow: hidden;
}

header {
    padding: 20px 25px;
    text-align: center;
}

.title {
    color: var(--heading-color);
    text-decoration: none;
}

.title:hover {
    color: var(--heading-color);
    background: none;
}

.title h1 {
    margin: 12px 0;
    font-size: clamp(1rem, 4vw, 1.5rem);
}

nav p {
    margin: 0;
}

nav a {
    display: inline-block;
    margin: 4px;
    padding: 2px 8px;
    color: var(--heading-color);
    text-decoration: none;
}

nav a:hover {
    color: var(--page-background);
    background: var(--heading-color);
}

main {
    padding: clamp(20px, 6vw, 40px);
}

strong,
b {
    color: var(--heading-color);
}

button {
    margin: 0;
    cursor: pointer;
}

table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
}

th,
td {
    padding: 6px 16px 6px 0;
    text-align: left;
}

th {
    border-bottom: 2px solid var(--heading-color);
}

hr {
    border: 0;
    border-top: 4px dashed var(--heading-color);
}

img,
video {
    max-width: 100%;
    height: auto;
    border: 4px solid var(--page-background);
}

code {
    padding: 2px 4px;
    background-color: var(--code-background-color);
    color: var(--code-color);
    font-family: monospace;
    text-shadow: none;
}

blockquote {
    margin: 1.5em 0;
    padding-left: 20px;
    border-left: 4px solid var(--blockquote-color);
    color: var(--blockquote-color);
    font-style: italic;
}

footer {
    padding: 25px 20px;
    text-align: center;
}

.inline {
    width: auto !important;
}

.highlight {
    margin-block: 1em;
    overflow-x: auto;
    background-color: var(--code-background-color);
    color: var(--code-color);
    box-shadow: 4px 4px 0 var(--page-background);
}

.highlight code {
    padding: 0;
}

/* blog post list */
ul.blog-posts {
    list-style-type: none;
    padding: unset;
}

ul.blog-posts li {
    display: flex;
    flex-wrap: wrap;
    column-gap: 1em;
    margin-bottom: .5em;
}

ul.blog-posts li span {
    flex: 0 0 8.5em;
}

ul.blog-posts li a {
    flex: 1 1 16em;
}

ul.blog-posts li a:visited {
    text-decoration-color: var(--visited-color);
}

