@media screen and (min-width: 768px) {
  body {
    display: grid;
    grid-template-columns: minmax(0, 24ch) minmax(0, 62ch);
    grid-template-rows: 1fr auto;
    justify-content: center;
    align-items: start;
    gap: var(--spacing) calc(var(--spacing) / 2);
  }
  header {
    grid-column: 1;
    grid-row: 1;
    position: sticky;
    top: var(--spacing);
    gap: var(--spacing);
  }
