    grid-column: 1;
    grid-row: 2;
    align-self: end;
  }
  nav p {
    flex-direction: column;
  }
  nav p a {
    width: 100%;
    gap: calc(var(--spacing) / 1.5);
    flex-direction: column;
    padding: calc(var(--spacing) / 1.5) var(--spacing);
  }
