    padding-block: 20px;
    line-height: 1.6;
    background-color: var(--paper-color);
    background-image: url(data:image/png;base64,);
}

main::before,
main::after {
    content: "";
    position: absolute;
    left: 0;
    width: 100%;
    height: 1px;
    background-color: var(--background-color);
    opacity: 0.5;
}

main::before {
    top: 7px;
}

main::after {
    bottom: 7px;
}

footer {
    padding-block: 25px;
    text-align: left;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    line-height: 1.2;
    text-wrap: balance;
}

a {
    cursor: pointer;
    text-decoration: none;
    color: var(--tea-color);
    border-bottom: 1px solid var(--tea-light-color);
    transition: color 0.3s, border-color 0.3s;
}

a:hover {
    text-decoration: none;
    color: var(--text-color);
    border-bottom-color: currentColor;
}

:focus-visible {
    outline: 2px solid var(--tea-color);
    outline-offset: 3px;
}

::selection {
    background: var(--tea-light-color);
}

header a,
.title,
.title:hover {
    color: var(--text-color);
    border-bottom: none;
}

nav a {
    margin-right: 8px;
}

nav a:hover {
    color: var(--tea-color);
}

button {
    margin: 0;
    cursor: pointer;
}

time {
    font-size: 0.85em;
}

table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
}

th,
td {
    padding: 4px 24px 4px 0;
    text-align: left;
    border-bottom: 1px solid var(--tea-light-color);
}

hr {
    border: 0;
    border-top: 1px dashed var(--tea-light-color);
}

img,
video {
    max-width: 100%;
    height: auto;
}

code {
    font-family: monospace;
    font-size: 0.8em;
    padding: 2px 4px;
    background-color: var(--code-background-color);
    color: #222;
    border-radius: 3px;
}

blockquote {
    margin-inline: 0;
    padding-left: 20px;
    border-left: 3px solid var(--tea-light-color);
    color: #4a4039;
    font-style: italic;
}

.inline {
    width: auto !important;
}

.highlight {
    background-color: var(--code-background-color);
    color: #222;
    border-radius: 3px;
    margin-block: 1em;
    overflow-x: auto;
    font-size: 0.8em;
}

.highlight code {
    font-size: 1em;
    padding: 0;
}

/* blog post list */
ul.blog-posts {
    list-style-type: none;
    padding: unset;
}

ul.blog-posts li {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: 1em;
    margin-bottom: 0.4em;
}

ul.blog-posts li span {
    flex: 0 0 6em;
    color: var(--tea-color);
}

ul.blog-posts li a {
    flex: 1 1 12em;
    color: var(--text-color);
    border-bottom: none;
}

ul.blog-posts li a:hover {
    color: var(--tea-color);
}

/* Font */
@import url("https://fonts.googleapis.com/css2?family=Cormorant+Garamond&display=swap");
/* Settings */
:root {
  --color-dark: #371722;
  --color-light: #fcfbf8;
  --color-primary: #ac9986;
  --size-step-0: clamp(1rem, calc(0.96rem + 0.22vw), 1.13rem);
  --size-step-1: clamp(1.25rem, calc(1.16rem + 0.43vw), 1.5rem);
  --size-step-2: clamp(1.56rem, calc(1.41rem + 0.76vw), 2rem);
  --size-step-3: clamp(1.95rem, calc(1.71rem + 1.24vw), 2.66rem);
  --size-step-4: clamp(2.44rem, calc(2.05rem + 1.93vw), 3.55rem);
  --spacing: 1.5rem;
  --align: center;
  --font-stack: "Cormorant Garamond", Georgia, Cambria, "Times New Roman", Times,
    serif;
}

/* HTML Styles */
html {
  font-size: 13px;
}
body {
  background: var(--color-light);
  color: var(--color-dark);
  padding: var(--spacing)
    clamp(calc(var(--spacing) / 2), 5vw, calc(var(--spacing) * 3));
  font-family: var(--font-stack);
  font-size: var(--size-step-1);
  line-height: 1.4;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  margin: 0;
}
* {
  box-sizing: border-box;
}
header,
main,
footer {
  width: 100%;
}
header {
  padding-bottom: var(--spacing);
  text-transform: uppercase;
  border-bottom: 2px solid var(--color-dark);
}
main {
  flex: 1;
  padding-bottom: calc(var(--spacing) * 2);
  text-align: var(--align);
}
main > p > i {
  display: block;
  border-top: 1px solid;
  border-bottom: 1px solid;
  max-width: 260px;
  margin-left: auto;
  margin-right: auto;
  padding: calc(var(--spacing) / 4);
}
a {
  color: var(--color-dark);
  text-decoration-color: var(--color-primary);
  text-decoration-thickness: 0.1ex;
  text-underline-offset: 0.3ex;
}
a:hover {
  text-decoration-thickness: 0.2ex;
}
img {
  display: block;
  max-width: 100%;
  margin: 0 auto;
  height: auto;
  filter: sepia(80%) grayscale(0.8) contrast(1) opacity(0.8);
  mix-blend-mode: multiply;
}
:is(h1, h2, h3, h4, h5) {
  line-height: 1.2;
  text-wrap: balance;
  margin-left: auto;
  margin-right: auto;
  margin-top: calc(var(--spacing) * 3);
  font-weight: 400;
  position: relative;
}

:is(h2, h3, h4, h5)::after {
  content: "";
  width: calc(var(--spacing) * 3);
  height: 2px;
  background-color: var(--color-dark);
  position: absolute;
  left: 0;
  right: 0;
  bottom: -0.5rem;
  margin: auto;
  border-radius: 1px;
}
h1 {
  font-size: var(--size-step-4);
  line-height: 1;
}
h2 {
  font-size: var(--size-step-3);
}
h3 {
  font-size: var(--size-step-2);
}
h4 {
  font-size: var(--size-step-1);
}
h5 {
  font-size: var(--size-step-0);
}
ul,
ol {
  -webkit-padding-start: var(--spacing);
  padding-inline-start: var(--spacing);
  text-align: left;
  column-count: 2;
}
li {
  margin: 0;
}

blockquote {
  font-style: italic;
  margin-left: auto;
  margin-right: auto;
}
blockquote p {
  font-size: var(--size-step-3);
}

/* Line lengths */
main,
header,
footer {
  max-width: 65ch;
  margin-inline: auto;
}
blockquote {
  max-width: 50ch;
}
h1 {
  max-width: 24ch;
}
h2,
h3 {
  max-width: 36ch;
}
/* Bear Content */
.title {
  text-decoration: none;
}
.title:hover {
  text-decoration: none;
  color: var(--color-primary);
}
.title h1 {
  font-size: var(--size-step-1);
  text-align: center;
  margin: 0;
  margin-bottom: calc(var(--spacing) / 2);
  max-width: 100%;
  color: var(--color-dark);
  letter-spacing: 1rem;
  text-shadow: 1px 1px 0px var(--color-light), 2px 2px 0px var(--color-primary);
}
nav p {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing);
  row-gap: 0;
  margin: 0;
  justify-content: center;
  font-size: var(--size-step-0);
}
nav p a {
  color: var(--color-dark);
  text-decoration: none;
}
ul.blog-posts {
  list-style-type: none;
  padding: unset;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: calc(var(--spacing) * 2);
}
ul.blog-posts li {
  margin: 0;
  display: flex;
  align-items: center;
  flex-direction: column;
}
ul.blog-posts li a {
  color: currentColor;
  max-width: 32ch;
  line-height: 1.2;
  font-size: var(--size-step-3);
}
ul.blog-posts li span {
  min-width: 11ch;
}
.highlight {
  padding: 1px var(--spacing);
  background-color: rgba(0, 0, 0, 0.1);
  border-radius: 3px;
  overflow-x: auto;
  line-height: 1.2;
  font-size: var(--size-step-0);
  text-align: left;
}
table {
  width: 100%;
}
footer {
  display: flex;
  justify-content: var(--align);
}
@media screen and (min-width: 600px) {
  html {
    font-size: 16px;
  }
  .title h1 {
    font-size: var(--size-step-3);
  }
}

