  --hover-background-color: light-dark(rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.12));
  --size-step-0: clamp(1rem, calc(0.96rem + 0.22vw), 1.13rem);
  --size-step-1: clamp(1.1rem, calc(1.03rem + 0.35vw), 1.3rem);
  --size-step-2: clamp(1.4rem, calc(1.28rem + 0.6vw), 1.75rem);
  --size-step-3: clamp(1.7rem, calc(1.5rem + 1vw), 2.3rem);
  --size-step-4: clamp(2.1rem, calc(1.8rem + 1.6vw), 3.2rem);
  --shadows-small: 0 5px 10px rgba(0, 0, 0, 0.125);
  --shadows-medium: 0 8px 30px rgba(0, 0, 0, 0.15);
