  line-height: 1.7;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  margin: 0;
  position: relative;
  background-image: linear-gradient(
      var(--color-border) 0.5px,
      transparent 0.5px,
      transparent calc(100% - 0.5px),
      var(--color-border) calc(100% - 0.5px)
    ),
    linear-gradient(
      90deg,
      var(--color-border) 0.5px,
      transparent 0.5px,
      transparent calc(100% - 0.5px),
      var(--color-border) calc(100% - 0.5px)
    );
  background-size: var(--spacing);
}
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: calc(var(--spacing) * 2);
  background: linear-gradient(var(--color-light), transparent);
  z-index: 1;
}
body::after {
  content: "";
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: calc(var(--spacing) * 2);
  background: linear-gradient(transparent, var(--color-light));
  z-index: 1;
}
